package com.bakeflow.shared.infrastructure.web;
import com.bakeflow.identity.IdentityException;import com.bakeflow.inventory.domain.DomainException;import com.bakeflow.integration.application.IntegrationException;import java.time.Instant;import java.util.Map;import org.slf4j.*;import org.springframework.dao.DataIntegrityViolationException;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestControllerAdvice public class ApiExceptionHandler{private static final Logger log=LoggerFactory.getLogger(ApiExceptionHandler.class);@ExceptionHandler(DomainException.class)ResponseEntity<Map<String,Object>>domain(DomainException e){return error(HttpStatus.BAD_REQUEST,e.getMessage());}@ExceptionHandler(DataIntegrityViolationException.class)ResponseEntity<Map<String,Object>>integrity(DataIntegrityViolationException e){log.warn("Database integrity operation failed");return error(HttpStatus.CONFLICT,"CONSTRAINT_VIOLATION");}@ExceptionHandler(IntegrationException.class)ResponseEntity<Map<String,Object>>integration(IntegrationException e){HttpStatus status=switch(e.code()){case "INVALID_CNPJ","INVALID_BARCODE"->HttpStatus.BAD_REQUEST;case "RATE_LIMIT_EXCEEDED"->HttpStatus.TOO_MANY_REQUESTS;default->HttpStatus.SERVICE_UNAVAILABLE;};return error(status,e.code());}@ExceptionHandler(IdentityException.class)ResponseEntity<Map<String,Object>>identity(IdentityException e){HttpStatus status=switch(e.code()){case "INVALID_CREDENTIALS","INVALID_REFRESH_TOKEN","REFRESH_TOKEN_REUSED","UNAUTHENTICATED"->HttpStatus.UNAUTHORIZED;case "RATE_LIMIT_EXCEEDED"->HttpStatus.TOO_MANY_REQUESTS;case "SESSION_NOT_FOUND","USER_NOT_FOUND"->HttpStatus.NOT_FOUND;case "INVALID_ORIGIN"->HttpStatus.FORBIDDEN;default->HttpStatus.BAD_REQUEST;};return error(status,e.code());}private ResponseEntity<Map<String,Object>>error(HttpStatus status,String message){var response=ResponseEntity.status(status);if(status==HttpStatus.TOO_MANY_REQUESTS)response.header("Retry-After","60");return response.body(Map.of("timestamp",Instant.now().toString(),"status",status.value(),"message",message));}}
